def solution(data):
    df_sales = next((df for n, df in data.items() if 'So_chi_tiet_ban_hang' in n), None)
    if df_sales is None:
        raise DataNotFoundError("Không tìm thấy bảng bán hàng phù hợp", table_name="bán hàng")

    cols = df_sales.columns.tolist()
    d_c = next((c for c in cols if any(k in str(c).lower() for k in ['ngày', 'date', 'thời gian'])), None)
    if d_c is None:
        raise DataNotFoundError("Không tìm thấy cột ngày trong bảng bán hàng")

    df_sales['clean_date'] = clean_date(df_sales[d_c])
    target_dates = ['2025-03-25', '2025-04-25', '2025-05-25']
    results = []

    for date_str in target_dates:
        mask = (df_sales['clean_date'].dt.date == pd.to_datetime(date_str).date())
        total_amount = clean_num(df_sales.loc[mask, 'Thành tiền']).sum()
        results.append(total_amount)

    return max(results)
